"""Plays the whole interactive tutorial in a real browser (keys generated by tools/tutorial_keys.ts).

Usage: python3 tools/e2e_tutorial.py <base_url> <keys.json> <outdir>
Checks: every step advances, the tutorial ends with the "done" modal, the profile gets tutorialDone,
and nothing is written to the run save or the statistics.
"""
import json, sys, time
from playwright.sync_api import sync_playwright

base, kp, out = sys.argv[1], sys.argv[2], sys.argv[3]
data = json.load(open(kp))
errors, fails = [], []

def check(name, ok, extra=''):
    print(('PASS ' if ok else 'FAIL ') + name + (f' — {extra}' if extra and not ok else ''))
    if not ok:
        fails.append(name)

with sync_playwright() as p:
    b = p.chromium.launch()
    page = b.new_page(viewport={'width': 1280, 'height': 800})
    page.on('pageerror', lambda e: errors.append(str(e)))
    page.on('console', lambda m: errors.append(m.text) if m.type == 'error' else None)
    page.goto(base)
    page.evaluate("localStorage.clear()")
    page.reload(); page.wait_for_selector('.loading.done', state='attached'); time.sleep(0.6)
    check('menu recommends the tutorial', page.locator('.menu-item.recommended', has_text='Samouczek').count() == 1)
    page.locator('.menu-item', has_text='Samouczek').click(); time.sleep(0.8)
    check('tutorial card shows step 1', 'krok 1 z 10' in page.locator('.tut-card').inner_text().lower())
    page.screenshot(path=f'{out}/tut-01-start.png')
    seen_steps = set()
    for i, k in enumerate(data['keys']):
        page.keyboard.press(k); time.sleep(0.09)
        if page.locator('.tut-card').count():
            txt = page.locator('.tut-card .tut-step').inner_text()
            seen_steps.add(txt)
        if i in (20, 30):
            page.screenshot(path=f'{out}/tut-{i:02d}.png')
    time.sleep(0.8)
    check('all 10 steps were shown', len(seen_steps) == 10, str(sorted(seen_steps)))
    check('done modal appears', page.get_by_text('Jesteś gotów na prawdziwą noc').count() == 1)
    page.screenshot(path=f'{out}/tut-99-done.png')
    prof = page.evaluate("JSON.parse(localStorage.getItem('lampiarz.profile.v1'))")
    check('profile.tutorialDone set', bool(prof and prof.get('tutorialDone')))
    check('tutorial not counted in stats', prof['stats']['runs'] == 0 and prof['stats']['kills'] == 0, str(prof['stats']))
    check('no achievements from the tutorial', prof['achievements'] == {}, str(prof['achievements']))
    check('tutorial never saved as a run', page.evaluate("localStorage.getItem('lampiarz.run.v1')") is None)
    page.get_by_role('button', name='Zacznij pierwszą noc').click(); time.sleep(0.5)
    check('after the tutorial: straight to night setup', page.get_by_role('button', name='Zapal pierwszą latarnię').count() == 1)
    page.get_by_role('button', name='Zapal pierwszą latarnię').click(); time.sleep(1.0)
    check('no old popup after the tutorial', page.get_by_role('button', name='Do roboty').count() == 0)
    check('objective tracker visible in a real night', page.locator('.objective').count() == 1)
    page.screenshot(path=f'{out}/tut-real-night.png')
    # mobile layout of the tutorial
    m = b.new_context(viewport={'width': 390, 'height': 844}, device_scale_factor=2, is_mobile=True, has_touch=True)
    mp = m.new_page()
    mp.on('pageerror', lambda e: errors.append(f'mobile: {e}'))
    mp.goto(base); mp.wait_for_selector('.loading.done', state='attached'); time.sleep(0.8)
    mp.locator('.menu-item', has_text='Samouczek').tap(); time.sleep(0.8)
    for _ in range(3):
        mp.get_by_role('button', name='Prawo').dispatch_event('pointerdown'); time.sleep(0.2)
    time.sleep(0.5)
    check('mobile: tutorial advances with the d-pad', 'krok 2' in mp.locator('.tut-card .tut-step').inner_text().lower())
    mp.screenshot(path=f'{out}/tut-mobile.png')
    b.close()

check('no page errors', not errors, '; '.join(errors[:5]))
print('RESULT', 'OK' if not fails else f'{len(fails)} FAILED')
sys.exit(1 if fails else 0)
